/* Explicit ten leisure actions. No map/search/label registrations, no new control scheme. */
function createInteractions103(B,scene,rig,world,life,hooks){
 const player=rig.player,V=(x,y,z)=>new B.Vector3(x,y,z),spots=life.spots,materials=new Map(),meshes=[],staticMeshes=[],colors={wood:'#947454',metal:'#405b60',cloth:'#a96e59',cream:'#f3e4c7',green:'#73916a',water:'#9cc9ce',navy:'#22394e',mustard:'#b88b3f'};
 function mat(k){if(materials.has(k))return materials.get(k);const m=new B.StandardMaterial('leisure103-'+k,scene);m.diffuseColor=B.Color3.FromHexString(colors[k]);m.specularColor=B.Color3.FromHexString('#161a17');materials.set(k,m);return m}
 function box(name,size,pos,k,parent){const m=B.MeshBuilder.CreateBox('life103-'+name,{width:size[0],height:size[1],depth:size[2]},scene);m.position.set(...pos);m.material=mat(k);m.parent=parent;m.isPickable=false;m.metadata={renderGroup99:'interaction-'+name.split('-')[0]};meshes.push(m);return m}
 function cyl(name,h,d,pos,k,parent){const m=B.MeshBuilder.CreateCylinder('life103-'+name,{height:h,diameter:d,tessellation:12},scene);m.position.set(...pos);m.material=mat(k);m.parent=parent;m.isPickable=false;meshes.push(m);return m}
 const roots=[];
 for(const s of spots){const root=new B.TransformNode('interaction103-'+s.id,scene);root.position.set(s.x,s.y,s.z);root.rotation.y=s.angle;roots.push(root);const start=meshes.length;
  if(['I02','I05'].includes(s.id)){box(s.id+'-seat',[s.id==='I05'?1.8:.65,.09,.65],[0,.47,0],'wood',root);for(const x of[-.25,.25])box(s.id+'-leg',[.07,.45,.48],[x,.225,0],'metal',root);box(s.id+'-back',[s.id==='I05'?1.8:.65,.4,.07],[0,.8,-.3],'wood',root);s.seatHeight=.515;if(s.id==='I02'){cyl(s.id+'-table',.07,.85,[0,.73,.9],'wood',root);cyl(s.id+'-pedestal',.72,.1,[0,.36,.9],'metal',root)}}
  if(s.id==='I04'){for(const x of[-.35,.35]){const m=box(s.id+'-easel',[.05,1.5,.05],[x,.75,.75],'wood',root);m.rotation.z=-x*.25}box(s.id+'-canvas',[.85,.65,.04],[0,1.12,.72],'cream',root);box(s.id+'-hill',[.75,.12,.012],[0,1,.69],'green',root);box(s.id+'-campus',[.36,.18,.012],[-.1,1.15,.69],'navy',root);box(s.id+'-sky',[.75,.10,.012],[0,1.36,.69],'water',root)}
  if(s.id==='I06'){cyl(s.id+'-pot',.25,.65,[0,.125,.8],'cloth',root);for(const x of[-.19,0,.19]){cyl(s.id+'-stem',.35,.035,[x,.4,.8],'green',root);const m=B.MeshBuilder.CreateSphere('life103-flower',{diameter:.16,segments:6},scene);m.position.set(x,.6,.8);m.parent=root;m.material=mat('cream');meshes.push(m)}}
  if(s.id==='I08'){cyl(s.id+'-pole',1.0,.13,[0,.5,.55],'metal',root);const tube=cyl(s.id+'-scope',.7,.22,[0,1.12,.55],'metal',root);tube.rotation.x=Math.PI/2;box(s.id+'-eyepiece',[.16,.16,.12],[0,1.12,.16],'navy',root)}
  if(s.id==='I09'){box(s.id+'-mat',[2.1,.025,1.65],[0,.0125,0],'cloth',root);box(s.id+'-basket',[.4,.3,.35],[.65,.17,.35],'wood',root);s.seatHeight=.04}
  // Merge only same material within this facility; never merge with another facility's mesh.
  const own=meshes.slice(start);for(const k of new Set(own.map(m=>m.material))){const parts=own.filter(m=>m.material===k);parts.forEach(m=>m.computeWorldMatrix(true));const merged=B.Mesh.MergeMeshes(parts,true,true,undefined,false,false);if(merged){merged.name='interaction103-'+s.id+'-'+k.name;merged.metadata={renderGroup99:'interaction103-'+s.id};merged.isPickable=false;merged.freezeWorldMatrix();staticMeshes.push(merged)}}
 }
 const props=new B.TransformNode('interaction103-hand-props',scene),held={};
 held.drink=cyl('held-cup',.22,.16,[.1,-.15,.12],'mustard',props);held.read=box('held-book',[.35,.035,.28],[.1,-.15,.18],'green',props);held.sketch=box('held-pencil',[.025,.27,.025],[.12,-.16,.16],'wood',props);held.water=cyl('held-can',.23,.25,[.12,-.15,.15],'metal',props);held.picnic=box('held-snack',[.14,.1,.14],[.1,-.15,.16],'cream',props);
 const page=box('held-page',[.32,.012,.25],[.1,-.124,.18],'cream',props);page.setEnabled(false);page.metadata={renderRole99:'actor'};
 const spout=box('held-spout',[.04,.04,.24],[.12,-.1,.33],'metal',props);held.water.metadata={};
 const drops=Array.from({length:6},(_,i)=>{const m=B.MeshBuilder.CreateSphere('interaction103-drop',{diameter:.035,segments:4},scene);m.material=mat('water');m.isPickable=false;m.setEnabled(false);m.metadata={renderRole99:'actor'};return m});
 Object.values(held).forEach(m=>{m.setEnabled(false);m.metadata={renderRole99:'actor'}});spout.setEnabled(false);spout.metadata={renderRole99:'actor'};
 const prompt=document.createElement('button');prompt.id='interaction103';prompt.hidden=true;document.body.append(prompt);let pendingSeat=false;let active=null,near=null,start=0,returnPoint=null,last=0,audio=null,lastBell=-1e9,bell=scene.meshes.find(m=>m.name==='plaza72-justice|bronze'),bellStart=-1e9;
 if(bell){bell.unfreezeWorldMatrix();bell.setPivotPoint(V(-19,world.floorAt(-19,352)+4.95,352));}
 function sound(){if(performance.now()-lastBell<3000)return;lastBell=performance.now();const volume=hooks.volume();if(volume<=0)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();for(const [f,amp]of [[440,.035],[660,.018],[1040,.01]]){const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=f;g.gain.setValueAtTime(amp*volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+1.4);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+1.45);o.onended=()=>{o.disconnect();g.disconnect()}}}catch{}}
 function valid(s){const st=hooks.state();return st.playing&&!st.paused&&!st.photo&&!st.airborne&&!st.bus&&!st.bag&&!st.waiting&&Math.hypot(player.position.x-s.x,player.position.z-s.z)<2.1&&Math.abs(player.position.y-.95-s.y)<.4;}
 function end(){if(!active)return;if(active.seated)hooks.releaseSeat?.();Object.values(held).forEach(m=>m.setEnabled(false));spout.setEnabled(false);page.setEnabled(false);drops.forEach(m=>m.setEnabled(false));props.parent=null;if(returnPoint)player.position.copyFrom(returnPoint);active=null;returnPoint=null;prompt.hidden=true;hooks.clear();}
 function interact(){if(active){end();return true}if(pendingSeat)return true;if(!near||!valid(near))return false;const s=near;if(s.seated&&hooks.claimSeat){pendingSeat=true;hooks.claimSeat('action:'+s.id).then(ok=>{pendingSeat=false;if(ok&&valid(s))begin(s);else if(ok)hooks.releaseSeat?.();}).catch(()=>{pendingSeat=false});return true}return begin(s);}function begin(s){returnPoint=player.position.clone();hooks.stop();active=s;start=performance.now();player.position.set(s.x,s.y+.95+(s.seated?(s.seatHeight??.04)-.32:0),s.z);player.rotation.y=s.angle;props.parent=rig.handAnchor(1);Object.entries(held).forEach(([key,m])=>m.setEnabled(key===s.action));spout.setEnabled(s.action==='water');page.setEnabled(s.action==='read');if(s.action==='bell'){sound();bellStart=start}return true;}
 prompt.onclick=()=>{interact();document.getElementById('world').focus()};
 function update(now,moving=false){const st=hooks.state();if(active&&(!st.playing||st.settings||st.bus||st.bag||st.waiting))end();if(active&&moving&&!st.photo)end();if(active&&active.duration&&(now-start)/1000>active.duration&&!st.photo)end();if(now-last>120){last=now;near=null;if(!active)for(const s of spots)if(valid(s)&&(!near||Math.hypot(player.position.x-s.x,player.position.z-s.z)<Math.hypot(player.position.x-near.x,player.position.z-near.z)))near=s;const show=st.playing&&!st.paused&&!st.photo&&!st.bus&&!st.waiting&&(active||near);prompt.hidden=!show;const text=active?'F 그만하기':'F '+(near?.label||'');if(prompt.textContent!==text)prompt.textContent=text;}
  if(bell&&now-bellStart<1800){bell.rotation.z=Math.sin((now-bellStart)*.012)*.07*Math.exp(-(now-bellStart)/650)}else if(bell)bell.rotation.z=0;
 }
 function pose(now){if(!active)return;const time=(now-start)/1000;rig.actionPose(active.action,time);if(active.action==='read')page.rotation.z=Math.max(0,Math.sin(time*.9))*.35;if(active.action==='water')for(let i=0;i<drops.length;i++){const m=drops[i],phase=(time*1.2+i/6)%1;m.setEnabled(true);m.position.set(active.x+Math.sin(active.angle)*(.35+phase*.4),active.y+.75-phase*.6,active.z+Math.cos(active.angle)*(.35+phase*.4));}}
 return{spots,staticMeshes,interact,end,update,pose,get active(){return active},get nearby(){return !!near},get seated(){return !!active?.seated},audit:()=>({count:spots.length,active:active?.id,near:near?.id,spots:spots.map(({id,label,x,y,z,action,seated})=>({id,label,x,y,z,action,seated})),effects:drops.filter(m=>m.isEnabled()).length})};
}
